const themes=[{tempo:180,notes:[67,71,74,79,74,71,69,74],bass:43},{tempo:330,notes:[60,64,67,71,69,67,64,62],bass:36},{tempo:210,notes:[57,60,64,63,57,60,64,67],bass:33},{tempo:240,notes:[60,67,72,76,79,76,72,67],bass:36},{tempo:160,notes:[64,67,69,72,69,67,64,62],bass:40},{tempo:200,notes:[60,72,61,69,64,67,62,65],bass:36},{tempo:400,notes:[45,52,57,52,45,52,55,52],bass:21},{tempo:290,notes:[57,64,69,72,76,72,69,64],bass:33},{tempo:195,notes:[67,69,71,74,76,74,71,69],bass:43}];
export class Music{constructor(){this.on=true;this.theme=0;this.i=0}start(){if(!this.ctx){this.ctx=new(window.AudioContext||window.webkitAudioContext)();this.g=this.ctx.createGain();this.g.gain.value=.35;this.g.connect(this.ctx.destination)}this.ctx.resume();this.set(this.theme)}tone(midi,d=.2,vol=.08,type='triangle'){if(!this.ctx||!this.on)return;const t=this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.value=440*2**((midi-69)/12);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g).connect(this.g);o.start(t);o.stop(t+d+.02)}set(n){this.theme=n;clearInterval(this.timer);this.i=0;if(!this.ctx)return;const a=themes[n];this.timer=setInterval(()=>{const i=this.i++;this.tone(a.notes[i%8],a.tempo/700,.08,n===6?'sine':'triangle');if(i%4===0){this.tone(a.bass,.6,.11,'sine');this.tone(a.notes[i%8]-12,.5,.035)}if(i%2===0&&![1,6,7].includes(n))this.tone(30,.05,.13,'sine')},a.tempo)}toggle(){this.on=!this.on;if(this.on)this.ctx?.resume();return this.on}sfx(name){const seq={goal:[72,76,79,84],talk:[72],hit:[32,30],whistle:[94,96],rewind:[48,60,72,84]}[name]||[60];seq.forEach((n,i)=>setTimeout(()=>this.tone(n,.15,.13,'triangle'),i*90))}}
